steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        issues(filter: {
          team: { name: { eq: \"Web\" } },
          state: { type: { eq: \"completed\" } },
          project: { name: { eq: \"Website Redesign\" } },
          completedAt: { eq: \"2024-08-14T00:00:00.000Z\" }
        }) {
          nodes {
            id
            identifier
            title
            description
            priority
            state { name }
            completedAt
            project { name }
            team { name }
          }
        }
      }
    "
  }'
